# Databricks notebook source
# MAGIC %md
# MAGIC # 12 · Create the "Demand Planning" AI/BI dashboard  ⚠️ SYNTHETIC DATA
# MAGIC
# MAGIC The dashboard is defined as code in **`dashboard/demand_planning.lvdash.json`** (generated by
# MAGIC `dashboard/build_dashboard.py`, kept in Git). This notebook:
# MAGIC 1. loads the definition and points it at your catalog
# MAGIC 2. **tests every dataset query** first (a broken query = an empty chart)
# MAGIC 3. creates the dashboard – or updates it if it already exists – with the Databricks Dashboards (Lakeview) API
# MAGIC 4. publishes it **without embedded credentials**: every viewer sees data with their own Unity Catalog permissions
# MAGIC
# MAGIC Pages: Overview · Forecast · Inventory risk · Accuracy & models · Anomalies · Insights, with global filters for
# MAGIC category, region, channel and SKU. Run notebooks 08–11 first (the dashboard reads their tables and views).

# COMMAND ----------

import os, sys, json
sys.path.insert(0, os.getcwd())
import pandas as pd
from dfp.config import load_config
from dfp.uc import resolve_catalog

CATALOG = resolve_catalog(load_config("dev"), spark.sql).catalog
DISPLAY_NAME = "Demand Planning"

definition_path = os.path.join(os.getcwd(), "..", "dashboard", "demand_planning.lvdash.json")
raw = open(definition_path, encoding="utf-8").read().replace("__CATALOG__", CATALOG)
dashboard = json.loads(raw)
print(f"loaded {len(dashboard['datasets'])} datasets and {len(dashboard['pages'])} pages for catalog `{CATALOG}`")

# COMMAND ----------

# MAGIC %md ## 1. Test every dataset query

# COMMAND ----------

results = []
for ds in dashboard["datasets"]:
    sql = "".join(ds["queryLines"])
    try:
        n = spark.sql(f"SELECT COUNT(*) AS n FROM ({sql})").first()["n"]
        results.append((ds["name"], n, "OK" if n > 0 else "EMPTY"))
    except Exception as e:
        results.append((ds["name"], 0, f"ERROR: {str(e).splitlines()[0][:150]}"))
check = pd.DataFrame(results, columns=["dataset", "rows", "status"])
display(check)
assert (check["status"] == "OK").all(), "fix the datasets above (run notebooks 08-11 first) before creating the dashboard"

# COMMAND ----------

# MAGIC %md ## 2. Create or update the dashboard, then publish it

# COMMAND ----------

from databricks.sdk import WorkspaceClient

w = WorkspaceClient()                                    # authenticates as you, inside the notebook
me = spark.sql("SELECT current_user() AS u").first()["u"]
parent_path = f"/Workspace/Users/{me}"

# a SQL warehouse runs the dashboard queries (Free Edition: "Serverless Starter Warehouse")
warehouses = list(w.warehouses.list())
assert warehouses, "no SQL warehouse found - create one under SQL Warehouses"
warehouse = sorted(warehouses, key=lambda x: (str(x.state) != "State.RUNNING", x.name))[0]
print("SQL warehouse:", warehouse.name, warehouse.id)

body = {"display_name": DISPLAY_NAME, "warehouse_id": warehouse.id, "parent_path": parent_path,
        "serialized_dashboard": json.dumps(dashboard)}

existing = [d for d in w.api_client.do("GET", "/api/2.0/lakeview/dashboards", query={"page_size": 100}).get("dashboards", [])
            if d.get("display_name") == DISPLAY_NAME and d.get("lifecycle_state", "ACTIVE") == "ACTIVE"]
if existing:
    dashboard_id = existing[0]["dashboard_id"]
    w.api_client.do("PATCH", f"/api/2.0/lakeview/dashboards/{dashboard_id}",
                    body={k: v for k, v in body.items() if k != "parent_path"})
    action = "updated"
else:
    dashboard_id = w.api_client.do("POST", "/api/2.0/lakeview/dashboards", body=body)["dashboard_id"]
    action = "created"

w.api_client.do("POST", f"/api/2.0/lakeview/dashboards/{dashboard_id}/published",
                body={"warehouse_id": warehouse.id, "embed_credentials": False})

host = w.config.host.rstrip("/")
print(f"Dashboard {action} and published.")
print(f"Open (published): {host}/dashboardsv3/{dashboard_id}/published")
print(f"Edit (draft):     {host}/dashboardsv3/{dashboard_id}")
displayHTML(f'<h3><a href="{host}/dashboardsv3/{dashboard_id}/published" target="_blank">➜ Open the Demand Planning dashboard</a></h3>')

# COMMAND ----------

# MAGIC %md ## 3. Check

# COMMAND ----------

d = w.api_client.do("GET", f"/api/2.0/lakeview/dashboards/{dashboard_id}")
pages = [p["displayName"] for p in json.loads(d["serialized_dashboard"])["pages"]]
assert len(pages) == len(dashboard["pages"]), pages
print("pages:", pages)
print("PHASE 9b DASHBOARD: PASSED")
